// Parse Slack slash command: /task create [title] #[project] [P0..P3]
const body = $json.body || $json;
const headers = $json.headers || {};
const rawText = (body.text || '').trim();
const responseUrl = body.response_url || '';
const userName = body.user_name || 'slack-user';

// Slack signature verification: v0=HMAC_SHA256(secret, "v0:" + timestamp + ":" + body)
const slackSig = headers['x-slack-signature'] || '';
const slackTs = headers['x-slack-request-timestamp'] || '';
const slackSecret = $env.SLACK_SIGNING_SECRET || '';
let isValidSlack = true;

if (slackSecret) {
  if (!slackSig || !slackTs) {
    isValidSlack = false;
  } else {
    const timeDiff = Math.abs(Math.floor(Date.now() / 1000) - Number(slackTs));
    if (timeDiff > 300) {
      isValidSlack = false;
    } else {
      const crypto = require('crypto');
      const sigBase = `v0:${slackTs}:${typeof body === 'string' ? body : JSON.stringify(body)}`;
      const hmac = crypto.createHmac('sha256', slackSecret);
      hmac.update(sigBase);
      const computed = 'v0=' + hmac.digest('hex');
      isValidSlack = (slackSig === computed);
    }
  }
}

if (!isValidSlack) {
  return [{
    json: {
      isValidSlack: false,
      ackMessage: '❌ Invalid or expired Slack signature.'
    }
  }];
}

const parts = rawText.split(/\s+/);
let action = parts[0]?.toLowerCase() || 'create';
let remaining = action === 'create' ? parts.slice(1) : parts;

let project = 'kubelab';
let priority = 'P2';
const titleWords = [];

for (const word of remaining) {
  if (word.startsWith('#')) {
    project = word.substring(1);
  } else if (['P0', 'P1', 'P2', 'P3'].includes(word.toUpperCase())) {
    priority = word.toUpperCase();
  } else {
    titleWords.push(word);
  }
}

const title = titleWords.join(' ') || 'Untitled Task';
const priorityMap = { 'P0': 4, 'P1': 3, 'P2': 2, 'P3': 1 };

return [{
  json: {
    title: title,
    project: project,
    priority: priority,
    priorityNum: priorityMap[priority] || 2,
    responseUrl: responseUrl,
    userName: userName,
    isValidSlack: isValidSlack,
    ackMessage: isValidSlack ? `⏳ Creating task *${title}* in project _#${project}_ (priority: ${priority})...` : '❌ Invalid or expired Slack request signature.'
  }
}];
